"""Immutable original finalized access-v3 archives, never regenerated by readers.

Captured at the pinned revision through actual owned loopback HTTP and original
family wrappers, engine, pipeline, scorer and checkpoints. UUIDs and time were
controlled before execution. No runtime producer is imported here.
"""

import hashlib
import json
from pathlib import Path


LEGACY_ACCESS_V3_REVISION = 'a9b27189296b55a114ccedb4638518d221be8b3c'
LEGACY_ACCESS_V3_SHA256 = {
    'zero': 'c505cd77917592740cb089a550a8df5f159f62621d2a0fa754f3c3bc2442df4a',
    'high': 'fe381071ae5bce4480436ece282f47d2b37a8b715dfd0b4dd0187544299a2a3c',
    'partial': '5aec767d958785d91cfaadd5b99c3caa86711c279774e6d5501ba3a906a22d40',
    'mixed': '990ef735649b1d25079e268e479b0decb91583acd6c1563eddbc39810e2b5337',
}
LEGACY_ACCESS_V3_NAMES = tuple(LEGACY_ACCESS_V3_SHA256)
_MANIFEST_SHA256 = '6fa4ba45a8af6328327cd5aae94a80be398cbaf3ee2c2d2af06bb575a288cd9f'
_ROOT = Path(__file__).parent / 'fixtures' / 'legacy_access_v3'


def legacy_access_v3_archive(name):
    """Return exact public bytes, refusing changed or unknown archives."""
    expected = LEGACY_ACCESS_V3_SHA256[name]
    raw = (_ROOT / (name + '.json')).read_bytes()
    if hashlib.sha256(raw).hexdigest() != expected:
        raise ValueError('Frozen access-v3 archive changed')
    return raw


def legacy_access_v3_report(name):
    """Load an independent copy without projecting or restamping history."""
    return json.loads(legacy_access_v3_archive(name))


def legacy_access_v3_manifest():
    """Return fixed original source hashes, IDs, probes, scores and counters."""
    raw = (_ROOT / 'manifest.json').read_bytes()
    if hashlib.sha256(raw).hexdigest() != _MANIFEST_SHA256:
        raise ValueError('Frozen access-v3 manifest changed')
    return json.loads(raw)
